379		public registerPromptFileProvider(extension: IExtensionDescription, type: PromptsType, provider: {
380			onDidChangePromptFiles?: Event<void>;
381			providePromptFiles: (context: IPromptFileContext, token: CancellationToken) => Promise<IPromptFileResource[] | undefined>;
382		}): IDisposable {
383			const providerEntry = { extension, type, ...provider };
384			this.promptFileProviders.push(providerEntry);
385	
386			const disposables = new DisposableStore();
387	
388			// Listen to provider change events to rerun computeListPromptFiles
389			if (provider.onDidChangePromptFiles) {
390				disposables.add(provider.onDidChangePromptFiles(() => {
391					this.invalidatePromptFileCache(type);
392				}));
393			}
394	
395			// Invalidate cache when providers change
396			this.invalidatePromptFileCache(type);
397	
398			disposables.add({
399				dispose: () => {
400					const index = this.promptFileProviders.findIndex((p) => p === providerEntry);
401					if (index >= 0) {
402						this.promptFileProviders.splice(index, 1);
403						this.invalidatePromptFileCache(type);
404					}
405				}
406			});
407	
408			return disposables;
409		}
