1698	class CachedPromise<T> extends Disposable {
1699		private cachedPromise: Promise<T> | undefined = undefined;
1700		private onDidUpdatePromiseEmitter: Emitter<void> | undefined = undefined;
1701	
1702		constructor(private readonly computeFn: (token: CancellationToken) => Promise<T>, private readonly getEvent: () => Event<void>, private readonly delay: number = 0) {
1703			super();
1704		}
