1706		public get onDidChange(): Event<void> {
1707			if (!this.onDidUpdatePromiseEmitter) {
1708				const emitter = this.onDidUpdatePromiseEmitter = this._register(new Emitter<void>());
1709				const delayer = this._register(new Delayer<void>(this.delay));
1710				this._register(this.getEvent()(() => {
1711					this.cachedPromise = undefined;
1712					delayer.trigger(() => emitter.fire());
1713				}));
1714			}
1715			return this.onDidUpdatePromiseEmitter.event;
1716		}
