1718		public get(token: CancellationToken): Promise<T> {
1719			if (this.cachedPromise !== undefined) {
1720				return this.cachedPromise;
1721			}
1722			const result = this.computeFn(token);
1723			if (!this.onDidUpdatePromiseEmitter) {
1724				return result; // only cache if there is an event listener
1725			}
1726			this.cachedPromise = result;
1727			this.onDidUpdatePromiseEmitter.fire();
1728			return result;
1729		}
