1752			super();
1753			this.onDidPromptModelChange = this._register(new Emitter<ModelChangeEvent>());
1754			const onAdd = (model: ITextModel) => {
1755				const promptType = getPromptsTypeForLanguageId(model.getLanguageId());
1756				if (promptType !== undefined) {
