1761				const promptType = getPromptsTypeForLanguageId(languageId);
1762				if (promptType !== undefined) {
1763					this.listeners.get(uri)?.dispose();
1764					this.listeners.delete(uri);
1765					this.onDidPromptModelChange.fire({ uri, promptType });
1766				}
1767			};
1768			this._register(modelService.onModelAdded(model => onAdd(model)));
1769			this._register(modelService.onModelLanguageChanged(e => {
1770				onRemove(e.oldLanguageId, e.model.uri);
1771				onAdd(e.model);
1772			}));
1773			this._register(modelService.onModelRemoved(model => onRemove(model.getLanguageId(), model.uri)));
1774		}
