	public async findRootRepositoryCustomizations(token: CancellationToken, result: IResolvedAgentFile[] = []): Promise<IResolvedAgentFile[]> {
		const searchRootRepoCustomizations = this.configService.getValue<boolean>(PromptsConfig.SEARCH_ROOT_REPO_CUSTOMIZATIONS) === true;
		if (!searchRootRepoCustomizations) {
			return result;
		}

		const visitedFolders = new ResourceSet();
		for (const folder of this.getWorkspaceFolders()) {
			let current = dirname(folder.uri);
			// walk up the parent directories until the filesystem root is reached
			while (!visitedFolders.has(current)) {
				if (token.isCancellationRequested) {
					return result;
				}
				visitedFolders.add(current);

				await this.findFilesInRoots([current], CLAUDE_MD_FILENAME, AgentFileType.claudeMd, token, result);
				await this.findFilesInRoots([joinPath(current, CLAUDE_CONFIG_FOLDER)], CLAUDE_MD_FILENAME, AgentFileType.claudeMd, token, result);
				await this.findFilesInRoots([joinPath(current, '.github')], COPILOT_CUSTOM_INSTRUCTIONS_FILENAME, AgentFileType.copilotInstructionsMd, token, result);
				await this.findFilesInRoots([current], AGENT_MD_FILENAME, AgentFileType.agentsMd, token, result);

				const parent = dirname(current);
				if (isEqual(parent, current)) {
					break; // reached the filesystem root
				}
				current = parent;
			}
		}

		return result;
	}

